\begin{tikzpicture}[x=0.65cm,y=0.8cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-0.8,-2.8) rectangle (5.8,2.5);
\draw[black,line width=0.5pt,->] (-0.6,0)--(5.5,0) node[right] {$x$};
