\begin{tikzpicture}[x=0.55cm,y=0.8cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-6.1,-2.9) rectangle (3,4.0);
\draw[black,line width=0.5pt,->] (-5.8,0)--(2.5,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-2.6)--(0,2.4) node[above] {$y$};
\draw[black,dashed,line width=0.4pt] (-5,-2.6)--(-5,2.1);
\node[above] at (-5,2.1) {$x=-5$};
\draw[black,line width=0.8pt] plot[domain=-4.94:2.3,samples=140] (\x,{ln(\x+5)/ln(3)});
\fill[black] (-4,0) circle (1.2pt) (0,{ln(5)/ln(3)}) circle (1.2pt);
\node[below] at (-4,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$-4$\special{dvisvgm:raw </g>}};
\node[below right] at (0,{ln(5)/ln(3)}) {$\log_3 5$};
\node[above left] at (-0.5,3.2) {$y=\log_3(x+5)$};
\end{tikzpicture}

